import { promises as fs } from "fs";
import path from "path";

// Every settlement in Eastern Province, Zambia — thousands of villages and hamlets from
// OpenStreetMap and GeoNames, generated by tools/settlements/fetch.py into
// public/settlements/eastern-province.json. The globe draws them as tiny dots; this helper
// answers "which health post serves this village" and "how many villages does this post serve".
// Pure functions: the same code runs on the server (API route) and in the browser (globe page).

export type Settlement = { n: string; la: number; ln: number; p: number | null; k: "city" | "town" | "village" | "hamlet" | "locality" | string };
export type SettlementFile = { sources: { osm: number; osmArea: string; geonames: number }; fetched: string; points: Settlement[] };
export type Post = { id: number; name: string; lat: number; lng: number };
export type Served = { post: Post; km: number };

const FILE = () => path.join(process.cwd(), "public", "settlements", "eastern-province.json");

let cached: SettlementFile | null = null;

// Server side: the generated file, read once and kept.
export async function load(): Promise<SettlementFile> {
  if (cached) return cached;
  const raw = await fs.readFile(FILE(), "utf8");
  cached = JSON.parse(raw) as SettlementFile;
  return cached;
}

const R = 6371;
export function kmBetween(aLat: number, aLng: number, bLat: number, bLng: number): number {
  const p1 = (aLat * Math.PI) / 180, p2 = (bLat * Math.PI) / 180;
  const dp = p2 - p1, dl = ((bLng - aLng) * Math.PI) / 180;
  const h = Math.sin(dp / 2) ** 2 + Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

// Settlements within `km` of a point, nearest first.
export function nearest(points: Settlement[], lat: number, lng: number, km: number): (Settlement & { km: number })[] {
  const dlat = km / 111; // quick box before the exact distance
  const out: (Settlement & { km: number })[] = [];
  for (const s of points) {
    if (Math.abs(s.la - lat) > dlat) continue;
    const d = kmBetween(lat, lng, s.la, s.ln);
    if (d <= km) out.push({ ...s, km: d });
  }
  return out.sort((a, b) => a.km - b.km);
}

// The nearest of the 40 health posts (SpacetimeDB's village table) to a settlement.
export function servedBy(s: { la: number; ln: number }, posts: Post[]): Served | null {
  let best: Served | null = null;
  for (const post of posts) {
    const km = kmBetween(s.la, s.ln, post.lat, post.lng);
    if (!best || km < best.km) best = { post, km };
  }
  return best;
}

// Every settlement assigned to its post, plus per-post totals ("serves N villages, ~P people").
export type Catchment = { count: number; people: number; named: number; withPopulation: number };
export function catchments(points: Settlement[], posts: Post[]): { assign: Int32Array; byPost: Map<number, Catchment> } {
  const assign = new Int32Array(points.length);
  const byPost = new Map<number, Catchment>();
  for (const post of posts) byPost.set(post.id, { count: 0, people: 0, named: 0, withPopulation: 0 });
  points.forEach((s, i) => {
    const hit = servedBy(s, posts);
    assign[i] = hit ? hit.post.id : -1;
    if (!hit) return;
    const c = byPost.get(hit.post.id)!;
    c.count++;
    c.named++;
    if (s.p) {
      c.people += s.p;
      c.withPopulation++;
    } else c.people += typicalPopulation(s.k);
  });
  return { assign, byPost };
}

// Most villages carry no population tag; these are the rough Eastern Province averages
// (2022 census: ~2.1 M people over roughly 8,000 named places) so the totals read as "~P people".
export function typicalPopulation(kind: string): number {
  switch (kind) {
    case "city": return 50000;
    case "town": return 8000;
    case "village": return 450;
    case "hamlet": return 120;
    default: return 60; // locality
  }
}

export const kindLabel = (k: string) => (k === "locality" ? "place" : k);
